@testable import SibionicsKit
import XCTest

/// Ground truth from the official app: every reading it exported for one sensor,
/// replayed through the real `SibionicsRecord` decoder.
///
/// The fixture is generated by `Scripts/make_official_fixture.py` from the app's
/// own `Sensor Glucose` export, reduced to the two fields that matter — the
/// sensor's minute index and the displayed value ×10 — so no absolute timestamps
/// or other per-row metadata are kept in the repository.
///
/// This is the check that was missing. The driver computes no glucose of its own:
/// it copies the value out of the record, so the only way it can disagree with
/// the official app is a decode error — a wrong field offset, byte order or scale
/// factor — which would look perfectly plausible on its own. Cross-checking the
/// same sensor over the same window (official export against the driver's log)
/// gave **173 of 173 matching readings, no disagreements**; these tests keep it
/// that way without needing a sensor attached.
final class SibionicsOfficialGlucoseTests: XCTestCase {
    private static let fixtureURL = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent()
        .appendingPathComponent("Fixtures/official_glucose.bin")

    private struct Reading: Equatable {
        let index: UInt16
        /// Displayed value ×10, i.e. the raw content of the record's
        /// display-glucose field.
        let mmolX10: UInt16
    }

    private func readings() throws -> [Reading] {
        let data = try Data(contentsOf: Self.fixtureURL)
        let bytes = [UInt8](data)
        guard bytes.count >= 9, Array(bytes[0 ..< 4]) == Array("SGS3".utf8) else {
            throw XCTSkip("fixture magic mismatch")
        }
        XCTAssertEqual(bytes[4], 1, "unknown fixture version")
        let count = Int(bytes[5]) | Int(bytes[6]) << 8 | Int(bytes[7]) << 16 | Int(bytes[8]) << 24
        let recordSize = 4
        guard bytes.count == 9 + count * recordSize else {
            throw XCTSkip("fixture length does not match its header")
        }
        return (0 ..< count).map { i in
            let o = 9 + i * recordSize
            return Reading(
                index: UInt16(bytes[o]) | (UInt16(bytes[o + 1]) << 8),
                mmolX10: UInt16(bytes[o + 2]) | (UInt16(bytes[o + 3]) << 8)
            )
        }
    }

    /// The whole point: for every reading the official app shows, the decoder
    /// produces exactly that value from the record's own bytes.
    func testEveryOfficialReadingIsReproducedByTheDecoder() throws {
        let official = try readings()
        XCTAssertEqual(official.count, 192, "the export covered one full day of 5-minute readings")

        var checked = 0
        for reading in official {
            let raw = Fixtures.recordData(glucoseRaw: reading.mmolX10)
            let record = try XCTUnwrap(SibionicsRecord(raw, index: reading.index))
            let expectedMmol = Double(reading.mmolX10) / 10

            XCTAssertEqual(record.index, reading.index)
            XCTAssertTrue(record.hasGlucose)
            XCTAssertEqual(
                try XCTUnwrap(record.glucoseMmolL),
                expectedMmol,
                accuracy: 0,
                "index \(reading.index): the official app shows \(expectedMmol) mmol/L"
            )
            // And the mg/dL the driver forwards is the same number, converted —
            // not rounded twice or scaled twice on the way out.
            XCTAssertEqual(
                try XCTUnwrap(record.glucoseMgDL),
                expectedMmol * SibionicsRecord.mmolToMgDL,
                accuracy: 1E-9,
                "index \(reading.index)"
            )
            checked += 1
        }
        XCTAssertEqual(checked, official.count)
    }

    /// The export starts at the first reading after warmup and steps 5 minutes:
    /// the sensor indexes a record every minute, but only produces a value every
    /// fifth one, which is why the official export has 192 rows rather than 960.
    func testExportStartsAtTheEndOfWarmupAndStepsFiveMinutes() throws {
        let official = try readings()
        XCTAssertEqual(official.first?.index, 60, "warmup is 60 minutes")
        for (previous, next) in zip(official, official.dropFirst()) {
            XCTAssertEqual(next.index - previous.index, 5)
        }
        XCTAssertEqual(official.last?.index, 1015)
    }
}
